export function getCat11And12Seeds() {
  const seeds = [];

  // 11: 70 artículos de Rescate Culinario y Técnicas Base
  RESCATE_Y_TECNICAS.forEach((r) => {
    const cleanSlug = r.title
      .toLowerCase()
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-|-$/g, "")
      .substring(0, 95)
      .replace(/-$/, "");

    seeds.push({
      slug: cleanSlug,
      title: r.title,
      category: "rescate-culinario-y-tecnicas",
      categoryName: "Rescate Culinario y Técnicas",
      focusKeyword: r.title.split("(")[0].split(":")[0].trim().toLowerCase(),
      layoutVariant: "duelo-insumos-rescate",
      schemaType: "HowTo",
      badgeLabel: `🧪 Técnica & Solución`,
      imageHint: "salsas",
      comparisonInfo: {
        optionA: {
          name: r.fix,
          badge: "✅ Técnica Correcta de Chef",
          score: "10 / 10",
          points: [
            "Corrige la textura, acidez, punto de sal o emulsión en pocos minutos",
            "Preserva el sabor tradicional peruano sin desperdiciar la olla",
          ],
        },
        optionB: {
          name: r.err,
          badge: "❌ Error Frecuente en Casa",
          score: "3.5 / 10",
          points: [
            "Altera negativamente la estructura de almidones o proteínas",
            "Puede arruinar el aderezo si no se corrige a tiempo",
          ],
        },
        verdict: r.verdict,
      },
      summary: `Guía de ciencia culinaria y rescate en cocina peruana: ${r.title}. ${r.verdict}`,
    });
  });

  // 12: 70 artículos de Calendario Festivo y Banquetes
  FESTIVO_Y_BANQUETES.forEach((f) => {
    const cleanSlug = f.title
      .toLowerCase()
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-|-$/g, "")
      .substring(0, 95)
      .replace(/-$/, "");

    seeds.push({
      slug: cleanSlug,
      title: f.title,
      category: "calendario-festivo-y-banquetes",
      categoryName: "Navidad, Fiestas Patrias y Banquetes",
      focusKeyword: f.title.split("(")[0].split(":")[0].trim().toLowerCase(),
      layoutVariant: "cronograma-fuego",
      schemaType: "Recipe",
      badgeLabel: `🎉 ${f.occ}`,
      imageHint: "mejores-platos",
      timelineSteps: [
        { phase: "Paso 1 (Planificación)", title: "Cálculo y Compras", pct: "25%", detail: `Selección de insumos frescos para ${f.occ}.` },
        { phase: "Paso 2 (Marinado / Base)", title: "Aderezo de Fiesta", pct: "50%", detail: `Tiempo de preparación y macerado (${f.time}).` },
        { phase: "Paso 3 (Cocción Principal)", title: "Secreto del Chef", pct: "80%", detail: f.tip },
        { phase: "Paso 4 (Mesa de Gala)", title: "Presentación y Guarnición", pct: "100%", detail: "Montaje en fuente caliente o buffet tradicional peruano." },
      ],
      summary: `Celebración gastronómica peruana (${f.occ}): ${f.title}. Tiempo: ${f.time}. Consejo clave: ${f.tip}`,
    });
  });

  return seeds;
}
